from glimmerquay import Ledger

def make_ledger():
    return Ledger(3, overflow="raise")

code_tasks.hidden_test:
from glimmerquay import Ledger, LedgerFullError
led = make_ledger()
assert isinstance(led, Ledger)
for i in range(3):
    led.append(i)
try:
    led.append(99)
except LedgerFullError:
    pass
else:
    raise AssertionError('a 4th append did not raise LedgerFullError')

