from glimmerquay import encode_frame

def frame_hello():
    return encode_frame(b"hello", checksum="xor8", pad_to=4)

from glimmerquay import decode_frame, encode_frame

def roundtrip(payload):
    return decode_frame(encode_frame(payload))

from glimmerquay import to_millivolts

def to_mv_list(values):
    return [to_millivolts(v, "uV") for v in values]

from glimmerquay import Cadence

def first_three_windows(start):
    return Cadence(2.5).windows(start, 3)

